Core.utils.deferBootstrap({elId:'bs-7',componentName:'@widget/HTML/bs-Component',props:JSON.parse("{\"data-aid\":\"AUTOIFRAME_RENDERED\",\"htmlSrc\":\"\u003C!-- SciTOX Accordion FAQ (Lime Green, Clean Master Version) -->\\n<section class=\\\"scitox-faq\\\">\\n  <style>\\n    .scitox-faq {\\n      --bg: #ffffff;\\n      --text: #111111;\\n      --muted: #525252;\\n      --lime: #84cc16;        /* Primary accent (lime green) */\\n      --lime-600: #65a30d;    /* Hover/active */\\n      --line: #e5e7eb;\\n      --callout: #f7fee7;     /* Pale lime background */\\n      --warn: #fee2e2;        /* Light red for warnings */\\n      max-width: 900px;\\n      margin: 0 auto;\\n      padding: 40px 20px;\\n      font-family: Helvetica, Arial, sans-serif;\\n      color: var(--text);\\n      line-height: 1.6;\\n      background: var(--bg);\\n    }\\n\\n    .scitox-faq h2 {\\n      text-align: center;\\n      font-size: 32px;\\n      font-weight: 800;\\n      margin: 0 0 28px 0;\\n      letter-spacing: -0.02em;\\n      color: var(--lime);\\n    }\\n\\n    .faq-note {\\n      background: var(--callout);\\n      border: 1px solid var(--lime);\\n      color: #1a2e05;\\n      padding: 12px 14px;\\n      border-radius: 12px;\\n      margin: 0 0 22px 0;\\n      font-size: 14px;\\n    }\\n\\n    .faq-accordion {\\n      display: grid;\\n      gap: 12px;\\n    }\\n\\n    .faq-accordion details {\\n      border: 1px solid var(--line);\\n      border-radius: 14px;\\n      background: #fff;\\n      overflow: hidden;\\n      transition: border-color 0.2s ease, box-shadow 0.2s ease;\\n    }\\n\\n    .faq-accordion details[open] {\\n      border-color: var(--lime);\\n      box-shadow: 0 4px 18px rgba(0,0,0,0.06);\\n    }\\n\\n    .faq-accordion summary {\\n      list-style: none;\\n      cursor: pointer;\\n      padding: 18px 56px 18px 18px;\\n      position: relative;\\n      font-weight: 700;\\n      font-size: 18px;\\n      color: var(--text);\\n      user-select: none;\\n    }\\n\\n    .faq-accordion summary::after {\\n      content: \\\"\\\";\\n      position: absolute;\\n      right: 16px;\\n      top: 50%;\\n      width: 22px;\\n      height: 22px;\\n      transform: translateY(-50%) rotate(0deg);\\n      border-radius: 50%;\\n      border: 2px solid var(--lime);\\n      background:\\n        conic-gradient(from 45deg, var(--lime) 0 90deg, transparent 90deg),\\n        conic-gradient(from 225deg, var(--lime) 0 90deg, transparent 90deg);\\n      background-size: 50% 50%;\\n      background-position: 25% 50%, 75% 50%;\\n      background-repeat: no-repeat;\\n      transition: transform 0.2s ease, border-color 0.2s ease;\\n    }\\n\\n    .faq-accordion details[open] summary::after {\\n      transform: translateY(-50%) rotate(45deg);\\n      border-color: var(--lime-600);\\n    }\\n\\n    .faq-accordion summary:hover { color: var(--lime-600); }\\n\\n    .faq-accordion .content {\\n      padding: 0 18px 18px 18px;\\n      color: var(--muted);\\n      font-size: 16px;\\n    }\\n\\n    .faq-accordion .content p { margin: 12px 0; }\\n    .faq-accordion .content ul { margin: 8px 0 8px 20px; }\\n    .faq-accordion .content li { margin: 6px 0; }\\n\\n    .callout {\\n      background: var(--callout);\\n      border-left: 4px solid var(--lime);\\n      padding: 10px 12px;\\n      border-radius: 10px;\\n      margin: 10px 0;\\n      color: #1a2e05;\\n    }\\n\\n    .warning {\\n      background: var(--warn);\\n      border-left: 4px solid #ef4444;\\n      padding: 10px 12px;\\n      border-radius: 10px;\\n      margin: 10px 0;\\n      color: #7f1d1d;\\n    }\\n\\n    .badge, .tag {\\n      display: inline-block;\\n      background: var(--lime);\\n      color: #0b1f03;\\n      font-weight: 800;\\n      padding: 2px 8px;\\n      border-radius: 999px;\\n      font-size: 12px;\\n      margin-left: 8px;\\n      vertical-align: middle;\\n    }\\n    .tag.new { background: #d1fae5; color: #065f46; border: 1px solid #10b981; }\\n\\n    @media (max-width: 540px) {\\n      .scitox-faq { padding: 28px 14px; }\\n      .scitox-faq h2 { font-size: 26px; }\\n      .faq-accordion summary { font-size: 17px; padding-right: 54px; }\\n      .faq-accordion .content { font-size: 15px; }\\n    }\\n  <\/style>\\n\\n  <h2>SciTOX Detox \u2013 Frequently Asked Questions</h2>\\n\\n  <div class=\\\"faq-note\\\">\\n    For best results, follow the instructions exactly. The recommended testing \u201Cgolden window\u201D is <strong>within 7 days</strong> of your final treatment.\\n  </div>\\n\\n  <div class=\\\"faq-accordion\\\">\\n    \u003C!-- Hair Detox FAQs -->\\n    <details>\\n      <summary>How effective is SciTOX at passing a hair follicle drug test?<span class=\\\"badge\\\">99.75%*</span></summary>\\n      <div class=\\\"content\\\">\\n        <p>SciTOX reports a <strong>99.75% success rate</strong> for customers who follow the instructions exactly. This covers cocaine, THC, meth, amphetamines, opiates, ketamine, alcohol/EtG, and more. Failures are extremely rare and often linked to skipped steps or incomplete treatments.</p>\\n        <p class=\\\"callout\\\"><em>*Documentation may be required for guarantee claims; see \u201CDo you offer a guarantee?\u201D</em></p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>How does SciTOX work?</summary>\\n      <div class=\\\"content\\\">\\n        <p>It\u2019s a multi-step chemical process that opens the hair cuticle, breaks down and detaches drug metabolites, removes them, and then reseals the hair. The treatment typically involves <strong>7 or more stages</strong>, with optional steps like bleaching and UV light for maximum effectiveness.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>How long does the detox take?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Plan for a minimum of <strong>3 hours</strong> from start to finish. Many customers complete the process in one session when necessary, but most repeat certain steps over at least a few days for added certainty.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>Are results permanent?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Yes\u2014SciTOX cleanses existing hair permanently; it doesn\u2019t just mask. However, <strong>new hair growth</strong> after treatment can contain metabolites if usage occurred prior to detox or continues afterward.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>Will it work on all substances?</summary>\\n      <div class=\\\"content\\\">\\n        <p>SciTOX targets a broad range, including: <em>cocaine/crack, THC, methamphetamine &amp; amphetamine/MDMA, opiates, ketamine, alcohol (EtG), and prescription stimulants like Adderall</em>.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>Will SciTOX damage my hair?</summary>\\n      <div class=\\\"content\\\">\\n        <p>The process can cause <strong>temporary dryness or brittleness</strong>, especially if you include optional bleach steps. Many customers feel the tradeoff is worth the clean test result. Use <em>deep conditioners</em> afterward to restore softness.</p>\\n      </div>\\n    </details>\\n\\n    \u003C!-- Bleach-related -->\\n    <details>\\n      <summary>Do I have to bleach my hair? I really don\u2019t want to</summary>\\n      <div class=\\\"content\\\">\\n        <p>No \u2014 bleaching is <strong>not required</strong> to use SciTOX successfully. The standard multi-step system was designed to work without bleach, and many customers pass by carefully following the 7-step protocol alone.</p>\\n        <p>Bleaching is an <strong>optional booster</strong> that can improve results in extreme cases (very heavy, long-term usage or darker, thicker hair types), but for most people it isn\u2019t necessary. If you prefer to avoid it, you can still achieve excellent results by repeating the recommended steps and spacing them over several days.</p>\\n        <p class=\\\"warning\\\"><strong>Note:</strong> If you do choose to add bleaching, expect some dryness or brittleness. Using deep conditioners afterward helps restore softness and shine.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>I am not allowed to bleach my hair. What can I do that is just as effective? Or what are my options?</summary>\\n      <div class=\\\"content\\\">\\n        <p>You still have <strong>strong options without bleach</strong>. SciTOX offers several effective alternatives that protect your hair while maintaining high success rates:</p>\\n        <ul>\\n          <li><strong>No Bleach Standard Replacement (Extra 12367)</strong> \u2013 A direct substitute for bleach that uses enhanced cleansing steps to break down and flush metabolites.</li>\\n          <li><strong>Premium No Bleach Option</strong> \u2013 Includes extra quantities of 12367 plus bonus <em>hair treatments, masks, and a custom shampoo</em> for added strength and recovery.</li>\\n          <li><strong>GentleTOX System</strong> \u2013 Newly released, formulated with <em>larger quantities of gentle cleansers, masks, and balanced-pH treatments</em>. It\u2019s less chemically concentrated to reduce irritation and hair strain. Recommended over at least <strong>2 weeks</strong> for maximum effectiveness with the least harsh effects.</li>\\n        </ul>\\n        <p class=\\\"callout\\\">All three options replace bleach protocols while keeping your hair healthy and your detox effective. If you have time, <strong>GentleTOX</strong> is generally the best balance of results and safety.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>Do you offer a guarantee?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Yes\u2014if you follow the instructions exactly and still fail, SciTOX offers a <strong>money-back guarantee</strong> (and in some cases, double your money back). <em>Proof of correct usage and official test results is required.</em></p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>Are reviews real?</summary>\\n      <div class=\\\"content\\\">\\n        <p>SciTOX publishes verified customer feedback through <strong>Yotpo</strong> and <strong>Trustpilot</strong>. Many independent users also share results on Reddit and other forums.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>How do I choose the right system?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Factors like drug type, usage history, hair length, and color affect which kit you need. <strong>Contact SciTOX support</strong> for a personalized recommendation.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>When should I test after treatment?</summary>\\n      <div class=\\\"content\\\">\\n        <p>The <strong>golden window</strong> is within <strong>7 days</strong> of treatment. This maximizes accuracy while avoiding regrowth contamination. Even better: use the system up to a day before the test if possible.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>Can I use other shampoos or products after SciTOX?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Avoid products that coat the hair (e.g., <em>silicones, heavy conditioners</em>) until after your test, as they may affect test penetration.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>How does a hair drug test work?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Labs take a <strong>~1.5-inch</strong> hair sample near the scalp (~90 days of history). They test for <em>drug metabolites embedded within the hair shaft</em>, not just surface residues.</p>\\n        <div class=\\\"warning\\\"><strong>Important:</strong> A \u201C90-day test\u201D label does not guarantee you\u2019ll pass if you stop for 90 days. With any consistent usage, people can fail for <strong>several months</strong> and sometimes up to a year+ with head hair. Body hair can reflect <strong>10\u201313 months</strong>.</div>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>Why do employers or courts use hair testing?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Hair testing is harder to cheat, detects a <strong>longer usage window</strong>, and provides a more complete picture than urine or saliva tests.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>Can bleaching or dyeing help you pass a test?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Cosmetic changes alone rarely work\u2014labs can still detect metabolites within the hair. SciTOX combines cosmetic changes with <strong>targeted chemical treatments</strong> designed to <em>remove</em> metabolites.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>How soon after use will drugs appear in hair?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Usually about <strong>7 days</strong> after use. Around <strong>10\u201314 days</strong>, hair has grown out far enough to be collected. Very recent use might not appear, but the next ~90 days of growth can retain a record.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>Can body hair be tested?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Yes\u2014body hair can reflect drug use over an even longer period because it grows more slowly. Typical detection windows are <strong>10\u201313 months</strong>.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>Are home hair drug tests reliable?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Some are accurate for screening, but most employers and courts require <strong>lab testing</strong> with confirmatory methods like <em>GC/MS</em> for official results.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>How long does it take (full protocol pacing)?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Plenty of people have used the system in a few hours the day of the test and passed for many substances and usage patterns. However, we recommend <strong>pacing over 3\u20134 days</strong> (or even a week if you have time) to minimize hair/scalp strain.</p>\\n        <p><strong>Frequent THC use with little/no clean time:</strong> use <em>twice the standard protocol</em>\u2014at least <strong>7\u20138 rounds</strong> of steps 1-2-3-6-7, <strong>two rounds</strong> of steps 4-5, plus a few bonus rounds, spaced over <strong>6\u20137 days</strong>.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>Is it permanent?</summary>\\n      <div class=\\\"content\\\">\\n        <p>It\u2019s permanent on the hair it\u2019s used on and generally permanent for people who have used only a few times\u2014except some edge cases (e.g., certain stimulants) that can grow out sporadically for up to a year, sometimes causing fluctuating results. Any <strong>consistent usage</strong> is likely to grow out for at least a few months, commonly <strong>6\u20137 months</strong>, and sometimes longer.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>If I'm clean for 90 days will I pass?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Not necessarily. The \u201C90-day\u201D label reflects the <strong>sample length</strong> (~1.5 inches \u2248 ~3 months), not a guarantee. Toxins used before those 90 days can still appear. Even <strong>a few uses of cocaine or meth</strong> can sometimes be detected for a year or more.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>If I used once will I pass?</summary>\\n      <div class=\\\"content\\\">\\n        <p>For <strong>THC</strong>, a single use will often pass, as it usually takes multiple uses for THC-COOH to be detectable. However, a <strong>single use</strong> of <em>meth, cocaine, some opiates, and most other drugs</em> can still be detected.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>How fast is shipping?</summary>\\n      <div class=\\\"content\\\">\\n        <p>Standard shipping is <strong>3\u20135 days</strong> and <strong>free over $250</strong>. Two-day and overnight options are available, with delivery windows (before 11 p.m., noon, or 8 a.m.) depending on the option selected.</p>\\n      </div>\\n    </details>\\n\\n    \u003C!-- NailTOX (NEW) -->\\n    <details>\\n      <summary>I read that you offer something for nail detox. Is that true? Can you tell me about it?<span class=\\\"tag new\\\">NEW</span></summary>\\n      <div class=\\\"content\\\">\\n        <p><strong>Yes \u2014 we now offer NailTOX.</strong> It\u2019s a one-size-fits-all product for all toxins. Like our hair detox systems, <strong>NailTOX</strong> is a multi-step process using cleansers, surfactants, and targeted chemical ingredients that work together to <em>oxidize, reduce, leach out, and destroy metabolites and metabolite bonds</em>. Some metabolites are transformed from detectable to undetectable forms.</p>\\n        <p><strong>UV Light is optional but very highly recommended</strong> for NailTOX kits \u2014 even more so than for hair kits. At specific wavelengths, UV light catalyzes reactions, improves penetration into the nail bed, and softens/rearranges keratin for better metabolite removal.</p>\\n        <p><em>NailTOX isn\u2019t as perfected as our hair products yet</em>, but it has improved rapidly over the past few months. For best results, we recommend <strong>cycling through the steps daily</strong>. Ideally, trim nails as short as possible and use the steps daily for about <strong>2 weeks</strong> as nails grow out to roughly <strong>2\u20133 mm</strong> (the length typically needed when 10 fingernails or toenails are collected for testing).</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>What is included with NailTOX?</summary>\\n      <div class=\\\"content\\\">\\n        <p><strong>NailTOX includes:</strong></p>\\n        <ul>\\n          <li><strong>Liquids &amp; gels</strong> \u2013 multi-step cleansing formulas designed for nails</li>\\n          <li><strong>Various applicators</strong> \u2013 for precise and even coverage</li>\\n          <li><strong>Two grades of nail files</strong> \u2013 optimized for thinning and prepping nails</li>\\n          <li><strong>Absorbent nail pads</strong> \u2013 soak up solution and allow gradual absorption into the nail</li>\\n          <li><strong>Fingertip covers</strong> \u2013 worn over the pads so you can \u201Capply and go\u201D throughout your day or night</li>\\n        </ul>\\n        <p class=\\\"callout\\\"><strong>UV Light is optional but strongly recommended</strong> with NailTOX kits for maximum effectiveness.</p>\\n      </div>\\n    </details>\\n\\n    <details>\\n      <summary>How effective is NailTOX?</summary>\\n      <div class=\\\"content\\\">\\n        <p>It\u2019s difficult to say with precision at this point, but current results suggest effectiveness is likely in the <strong>mid-80% range</strong>. Our newest version is showing significantly more promise, and early data suggests it may already be trending toward <strong>90%+</strong>.</p>\\n        <p>Like our hair systems, <strong>NailTOX is constantly improving</strong>. It has advanced dramatically in just the past few months \u2014 many times better this month than last, and last month was already significantly improved over three months prior.</p>\\n        <p class=\\\"callout\\\">We\u2019re confident that within <strong>6\u201312 months</strong>, NailTOX will achieve effectiveness in the <strong>99% range</strong> like our hair detox systems. But we still have <em>hundreds to thousands of experiments to go</em> \u2014 optimizing step order, refining protocols per usage pattern, and potentially creating specific products for specific toxins.</p>\\n      </div>\\n    </details>\\n    \u003C!-- /NailTOX -->\\n  </div>\\n</section>\\n\",\"order\":0,\"widgetId\":\"59cbd05b-0728-415d-bfd5-452342bd1781\",\"section\":\"default\",\"category\":\"accent\",\"locale\":\"en-US\",\"env\":\"production\",\"renderMode\":\"PUBLISH\"}"),context:JSON.parse("{\"widgetId\":\"59cbd05b-0728-415d-bfd5-452342bd1781\",\"widgetType\":\"HTML\",\"widgetPreset\":\"html1\",\"group\":\"Section\",\"groupType\":\"Default\",\"section\":\"default\",\"category\":\"accent\",\"fontSize\":\"medium\",\"fontFamily\":\"alternate\",\"websiteThemeOverrides\":{},\"widgetThemeOverrides\":{}}"),contextKey:'context-bs-7',radpack:"@widget/HTML/bs-Component"},false);
Core.utils.deferBootstrap({elId:'bs-8',componentName:'@widget/PDF/bs-Component',props:JSON.parse("{\"pdfUrl\":\"//img1.wsimg.com/blobby/go/70f51a51-acc5-486a-8b72-0544e77d15d9/SciTOX_Frequently_Asked_Questions_About_Hair_F.pdf\",\"staticContent\":{\"defaultSectionTitle\":\"PDF Viewer\",\"defaultDownloadLink\":\"Download PDF\",\"placeholderTextPublish\":\"File coming soon.\",\"placeholderTextEditor\":\"Add a PDF file to get started.\",\"loadingStateMessage\":\"Loading files\",\"previous\":\"Previous\",\"next\":\"Next\"},\"isMobile\":null,\"widgetId\":\"5c5f9b21-0b0f-479f-ae25-052ca552f2ed\",\"section\":\"alt\",\"category\":\"accent\",\"locale\":\"en-US\",\"env\":\"production\",\"renderMode\":\"PUBLISH\"}"),context:JSON.parse("{\"order\":1,\"widgetId\":\"5c5f9b21-0b0f-479f-ae25-052ca552f2ed\",\"widgetType\":\"PDF\",\"widgetPreset\":\"pdf1\",\"group\":\"Section\",\"groupType\":\"Default\",\"section\":\"alt\",\"category\":\"accent\",\"fontSize\":\"medium\",\"fontFamily\":\"alternate\",\"websiteThemeOverrides\":{},\"widgetThemeOverrides\":{}}"),contextKey:'context-bs-7',radpack:"@widget/PDF/bs-Component"},false);
Core.utils.deferBootstrap({elId:'bs-9',componentName:'@widget/HTML/bs-Component',props:JSON.parse("{\"data-aid\":\"AUTOIFRAME_RENDERED\",\"htmlSrc\":\"<section style=\\\"max-width:900px; margin:auto; padding:40px 20px; font-family:Helvetica, Arial, sans-serif; line-height:1.6; color:#111;\\\">\\n  <h2 style=\\\"text-align:center; font-size:32px; font-weight:700; color:#0d9488; margin-bottom:30px;\\\">\\n    SciTOX Detox \u2013 Frequently Asked Questions\\n  </h2>\\n\\n  <div style=\\\"margin-bottom:25px;\\\">\\n    <h3 style=\\\"color:#0d9488; font-size:20px; margin-bottom:8px;\\\">How effective is SciTOX at passing a hair follicle drug test?</h3>\\n    <p>SciTOX reports a <strong style=\\\"color:#0d9488;\\\">99.75% success rate</strong> for customers who follow the instructions exactly. This covers cocaine, THC, meth, amphetamines, opiates, ketamine, alcohol/EtG, and more. Failures are extremely rare and often linked to skipped steps or incomplete treatments.</p>\\n  </div>\\n\\n  <div style=\\\"margin-bottom:25px;\\\">\\n    <h3 style=\\\"color:#0d9488; font-size:20px; margin-bottom:8px;\\\">How does SciTOX work?</h3>\\n    <p>It\u2019s a multi-step chemical process that opens the hair cuticle, breaks down and detaches drug metabolites, removes them, and then reseals the hair. The treatment typically involves 7 or more stages, with optional steps like bleaching and UV light treatment for maximum effectiveness.</p>\\n  </div>\\n\\n  <div style=\\\"margin-bottom:25px;\\\">\\n    <h3 style=\\\"color:#0d9488; font-size:20px; margin-bottom:8px;\\\">How long does the detox take?</h3>\\n    <p>Plan for a minimum of <strong>3 hours</strong> from start to finish. Many customers complete the process in one session, but most repeat certain steps over several days for added certainty.</p>\\n  </div>\\n\\n  <div style=\\\"margin-bottom:25px;\\\">\\n    <h3 style=\\\"color:#0d9488; font-size:20px; margin-bottom:8px;\\\">Are results permanent?</h3>\\n    <p>Yes, SciTOX cleanses existing hair permanently\u2014it doesn\u2019t just mask the drugs. However, new hair growth after treatment will contain metabolites if usage occurred prior to detox or continues afterward.</p>\\n  </div>\\n\\n  <div style=\\\"margin-bottom:25px;\\\">\\n    <h3 style=\\\"color:#0d9488; font-size:20px; margin-bottom:8px;\\\">Will SciTOX damage my hair?</h3>\\n    <p>The process can cause <span style=\\\"color:#e11d48;\\\">temporary dryness or brittleness</span>, especially with optional bleach steps. Deep conditioners after treatment restore softness and manageability.</p>\\n  </div>\\n\\n  <div style=\\\"margin-bottom:25px; border-left:4px solid #0ea5e9; padding-left:15px;\\\">\\n    <h3 style=\\\"color:#0d9488; font-size:20px; margin-bottom:8px;\\\">Important Notes:</h3>\\n    <ul style=\\\"margin:0; padding-left:18px;\\\">\\n      <li>The \u201Cgolden window\u201D for testing is <strong>within 7 days</strong> of treatment.</li>\\n      <li>A \u201C90-day hair test\u201D doesn\u2019t guarantee passing after 90 days clean\u2014consistent use can still show up for months, sometimes up to a year.</li>\\n      <li>Body hair retains history even longer (10\u201313 months).</li>\\n    </ul>\\n  </div>\\n\\n  \u003C!-- Repeat the above Q/A structure for the rest of your FAQs -->\\n</section>\\n\",\"widgetId\":\"e3be5993-f205-4cd2-889f-3125f228c5de\",\"section\":\"default\",\"category\":\"primary\",\"locale\":\"en-US\",\"env\":\"production\",\"renderMode\":\"PUBLISH\"}"),context:JSON.parse("{\"order\":2,\"widgetId\":\"e3be5993-f205-4cd2-889f-3125f228c5de\",\"widgetType\":\"HTML\",\"widgetPreset\":\"html1\",\"group\":\"Section\",\"groupType\":\"Default\",\"section\":\"default\",\"category\":\"primary\",\"fontSize\":\"medium\",\"fontFamily\":\"alternate\",\"websiteThemeOverrides\":{},\"widgetThemeOverrides\":{}}"),contextKey:'context-bs-7',radpack:"@widget/HTML/bs-Component"},false);
